_CORE_SRC = '# Action format: "[(from_node, to_node, count), ...]"\n# Payout: "capacity_i = drones_i * drone_capacity";\n# "served_i = capacity_i * demand / max(total_capacity, demand)".\n# Cost: "upkeep_i = UPKEEP * (DRONES_PER_PLAYER - drones_i at own base)".\n# Moves use only start-of-turn drones; every drone moves at most one edge.\n\nimport heapq\nimport time\nfrom collections import deque\n\nTIME_BUDGET = 0.25\nN_TURNS = 100\nDRONE_CAPACITY = 5\nUPKEEP = 2.0\n\n\ndef served(own, opponent, demand):\n    capacity = DRONE_CAPACITY * own\n    total_capacity = DRONE_CAPACITY * (own + opponent)\n    denominator = max(total_capacity, demand)\n    return capacity * demand / denominator if denominator > 0 else 0.0\n\n\ndef score_difference(own, opponent, demand):\n    return served(own, opponent, demand) - served(opponent, own, demand)\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for u, v in edges:\n        if 0 <= u < n and 0 <= v < n and u != v:\n            adjacency[u].append(v)\n            adjacency[v].append(u)\n    for neighbors in adjacency:\n        neighbors.sort()\n\n    distances = []\n    for source in range(n):\n        row = [-1] * n\n        row[source] = 0\n        queue = deque([source])\n        while queue:\n            u = queue.popleft()\n            for v in adjacency[u]:\n                if row[v] < 0:\n                    row[v] = row[u] + 1\n                    queue.append(v)\n        distances.append(row)\n\n    hops = [[-1] * n for _ in range(n)]\n    for source in range(n):\n        for target in range(n):\n            if distances[source][target] > 0:\n                hops[source][target] = next(\n                    v for v in adjacency[source]\n                    if distances[v][target] == distances[source][target] - 1\n                )\n    return adjacency, distances, hops\n\n\ndef legal_action(have, wanted, adjacency, distances, hops):\n    """Closest-first transport, validated against untouched starting inventories."""\n    n = len(have)\n    surplus = [max(0, have[i] - wanted[i]) for i in range(n)]\n    deficit = [max(0, wanted[i] - have[i]) for i in range(n)]\n    pairs = sorted(\n        (distances[s][t], s, t)\n        for s in range(n) if surplus[s]\n        for t in range(n) if deficit[t] and distances[s][t] > 0\n    )\n    aggregated = {}\n    reservations = []\n    for _, source, target in pairs:\n        count = min(surplus[source], deficit[target])\n        if not count:\n            continue\n        hop = hops[source][target]\n        if hop < 0:\n            continue\n        surplus[source] -= count\n        deficit[target] -= count\n        key = (source, hop)\n        aggregated[key] = aggregated.get(key, 0) + count\n        reservations.append((hop, target, count))\n\n    available = list(have)\n    action = []\n    for (source, destination), count in sorted(aggregated.items()):\n        if destination not in adjacency[source]:\n            continue\n        count = min(count, available[source])\n        if count > 0:\n            available[source] -= count\n            action.append((int(source), int(destination), int(count)))\n    # Units already at their destination should also retain their preference.\n    for node in range(n):\n        count = min(have[node], wanted[node])\n        if count:\n            reservations.append((node, node, count))\n    return action, reservations\n\n\nclass Strategy:\n    def __init__(self, player_id):\n        self.player_id = player_id\n        self.map_key = None\n        self.adjacency = None\n        self.distances = None\n        self.hops = None\n        self.reservations = []\n        self.last_turn = None\n        self.bad_reports = 0\n\n    def _plan(self, obs, deadline):\n        have = list(obs["player_drones"])\n        opponent = obs["opponent_drones"]\n        n = len(have)\n        base = int(obs["player_base"])\n        turn = int(obs.get("turn", 0))\n        remaining = max(1, N_TURNS - turn)\n        horizon = min(12, remaining)\n        forecast = obs.get("demand_forecast", [])\n        distances = self.distances\n\n        # The tail uses the last exact forecast, not an invented demand spike.\n        values = []\n        for node in range(n):\n            row = forecast[node] if node < len(forecast) else []\n            values.append([\n                float(row[min(k, len(row) - 1)]) if row else 0.0\n                for k in range(horizon)\n            ])\n\n        sticky = {}\n        if self.last_turn is not None and turn == self.last_turn + 1:\n            for source, target, count in self.reservations:\n                if 0 <= source < n and count > 0:\n                    sticky[(source, target)] = sticky.get((source, target), 0) + count\n\n        available = list(have)\n        wanted = [0] * n\n        used_preferences = {}\n        cache = {}\n\n        def marginal(source, target, count):\n            distance = distances[source][target]\n            if distance < 0:\n                return -1e30\n            # A distance-one deployment earns on the current turn.\n            delay = max(0, distance - 1)\n            if delay >= horizon:\n                return -1e30\n\n            key = (target, count, delay)\n            if key not in cache:\n                other = opponent[target]\n                gain = 0.0\n                for k in range(delay, horizon):\n                    demand = values[target][k]\n                    gain += (\n                        score_difference(count + 1, other, demand)\n                        - score_difference(count, other, demand)\n                        - UPKEEP\n                    )\n                # Transit is charged even though its incidental revenue is ignored.\n                gain -= UPKEEP * delay\n                cache[key] = gain\n            gain = cache[key]\n\n            # Compare deployment with the feasible alternative of returning home.\n            home_delay = max(0, distances[source][base] - 1)\n            gain += UPKEEP * min(horizon, home_delay)\n\n            preference = sticky.get((source, target), 0)\n            used = used_preferences.get((source, target), 0)\n            if preference > used:\n                gain += 1.15\n            elif source == target:\n                gain += 0.35\n            return gain\n\n        # Heap entries are refreshed lazily as target marginal values change.\n        heap = []\n        for source in range(n):\n            if not available[source]:\n                continue\n            for target in range(n):\n                if target == base or not any(values[target]):\n                    continue\n                gain = marginal(source, target, 0)\n                heapq.heappush(heap, (-gain, source, target, 0, 0))\n\n        iterations = 0\n        while heap:\n            iterations += 1\n            if iterations % 32 == 0 and time.perf_counter() >= deadline:\n                break\n            neg_gain, source, target, version, pref_version = heapq.heappop(heap)\n            if available[source] <= 0:\n                continue\n            current_pref = used_preferences.get((source, target), 0)\n            if version != wanted[target] or pref_version != current_pref:\n                gain = marginal(source, target, wanted[target])\n                heapq.heappush(\n                    heap, (-gain, source, target, wanted[target], current_pref)\n                )\n                continue\n            if -neg_gain <= 0.15:\n                break\n            available[source] -= 1\n            wanted[target] += 1\n            used_preferences[(source, target)] = current_pref + 1\n            if available[source]:\n                gain = marginal(source, target, wanted[target])\n                heapq.heappush(\n                    heap,\n                    (-gain, source, target, wanted[target], current_pref + 1),\n                )\n\n        wanted[base] += sum(available)\n        return wanted\n\n    def act(self, obs):\n        start = time.perf_counter()\n        deadline = start + max(0.0, 0.58 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n        have = obs.get("player_drones", [])\n        if len(have) != n or len(obs.get("opponent_drones", [])) != n:\n            return []\n\n        edges = obs.get("edges", [])\n        key = (n, tuple((int(u), int(v)) for u, v in edges))\n        if key != self.map_key:\n            self.adjacency, self.distances, self.hops = preprocess_map(n, edges)\n            self.map_key = key\n            self.reservations = []\n\n        bad = (\n            not obs.get("action_format_correct_last_turn", True)\n            or obs.get("n_invalid_actions_last_turn", 0) > 0\n        )\n        if bad:\n            self.bad_reports += 1\n\n        if self.bad_reports >= 2:\n            # A deliberately simple, conservative fallback: return drones home.\n            wanted = [0] * n\n            wanted[int(obs["player_base"])] = sum(have)\n        else:\n            wanted = self._plan(obs, deadline)\n\n        action, reservations = legal_action(\n            have, wanted, self.adjacency, self.distances, self.hops\n        )\n        self.reservations = reservations\n        self.last_turn = int(obs.get("turn", 0))\n        return action\n'
_CORE_CLASS = 'Strategy'
_FALLBACK_SRC = '# Exact action format: [(from_node, to_node, count), ...]\n# Revenue: "capacity_i = drones_i * drone_capacity"\n#          "served_i = capacity_i * demand / max(total_capacity, demand)"\n# Cost: "UPKEEP = 2.0" per drone away from its own base, per turn.\n# Moves happen before payout; each drone moves at most one edge per turn.\n\nfrom collections import deque\nimport time\n\nTIME_BUDGET = 0.25\n\nN_TURNS = 100\nDRONE_CAPACITY = 5\nUPKEEP = 2.0\n\n\ndef preprocess_map(n, edges):\n    adjacency = [[] for _ in range(n)]\n    for a, b in edges:\n        if 0 <= a < n and 0 <= b < n and a != b:\n            adjacency[a].append(b)\n            adjacency[b].append(a)\n    adjacency = [sorted(set(row)) for row in adjacency]\n\n    distances = []\n    for start in range(n):\n        row = [-1] * n\n        row[start] = 0\n        queue = deque([start])\n        while queue:\n            node = queue.popleft()\n            for other in adjacency[node]:\n                if row[other] < 0:\n                    row[other] = row[node] + 1\n                    queue.append(other)\n        distances.append(row)\n\n    next_hop = [[s for _ in range(n)] for s in range(n)]\n    for source in range(n):\n        for target in range(n):\n            if distances[source][target] > 0:\n                next_hop[source][target] = next(\n                    v for v in adjacency[source]\n                    if distances[v][target] == distances[source][target] - 1\n                )\n    return adjacency, distances, next_hop\n\n\ndef payout(own, opponent, demand):\n    capacity = own * DRONE_CAPACITY\n    total_capacity = (own + opponent) * DRONE_CAPACITY\n    denominator = max(total_capacity, demand)\n    if denominator <= 0:\n        return 0.0\n    return capacity * demand / denominator\n\n\ndef trajectory(source, target, horizon, next_hop):\n    result = []\n    node = source\n    for _ in range(horizon):\n        if node != target:\n            node = next_hop[node][target]\n        result.append(node)\n    return result\n\n\ndef legal_action(plans, start_counts, adjacency):\n    aggregated = {}\n    for source, path in plans:\n        if path and path[0] != source:\n            key = (source, path[0])\n            aggregated[key] = aggregated.get(key, 0) + 1\n\n    available = list(start_counts)\n    result = []\n    for (source, target), count in sorted(aggregated.items()):\n        if not (0 <= source < len(available) and\n                0 <= target < len(available)):\n            continue\n        if target not in adjacency[source] or source == target:\n            continue\n        count = min(count, available[source])\n        if count > 0:\n            result.append((int(source), int(target), int(count)))\n            available[source] -= count\n    return result\n\n\ndef make_plan(obs, distances, next_hop, deadline, conservative):\n    n = len(distances)\n    home = int(obs["player_base"])\n    counts = obs["player_drones"]\n    opponent = obs["opponent_drones"]\n    forecasts = obs["demand_forecast"]\n    remaining = max(0, N_TURNS - int(obs.get("turn", 0)))\n    horizon = min(5, remaining, min((len(f) for f in forecasts), default=0))\n    if horizon <= 0:\n        return []\n\n    # Every unassigned drone has a safe default: go straight home.\n    # Forecast occupancy includes all units in transit, not just their targets.\n    plans = []\n    occupancy = [[0] * n for _ in range(horizon)]\n    for source in range(n):\n        path = trajectory(source, home, horizon, next_hop)\n        for _ in range(max(0, int(counts[source]))):\n            plans.append((source, path[:]))\n            for k, node in enumerate(path):\n                occupancy[k][node] += 1\n\n    # Existing deployed units get first choice; reserve units are assigned last.\n    plans.sort(key=lambda item: (item[0] == home, item[0]))\n\n    def terminal_cost(node):\n        # Conservative liability for returning home after the exact forecast.\n        # No future revenue or unknown demand is credited.\n        return UPKEEP * max(0, distances[node][home])\n\n    def incremental_value(path):\n        value = -terminal_cost(path[-1])\n        for k, node in enumerate(path):\n            own = occupancy[k][node]\n            demand = float(forecasts[node][k])\n            value += (\n                payout(own + 1, opponent[node], demand)\n                - payout(own, opponent[node], demand)\n            )\n            if node != home:\n                value -= UPKEEP\n        return value\n\n    for index, (source, old_path) in enumerate(plans):\n        if time.perf_counter() >= deadline:\n            break\n        for k, node in enumerate(old_path):\n            occupancy[k][node] -= 1\n\n        best_path = old_path\n        best_value = incremental_value(old_path)\n        # Avoid marginal fights entirely. The exact payout still accounts for\n        # opponents on intermediate nodes along each route.\n        targets = sorted(\n            (v for v in range(n)\n             if v != home and opponent[v] == 0\n             and 0 <= distances[source][v] <= horizon),\n            key=lambda v: (distances[source][v], v),\n        )\n        if not conservative:\n            for target in targets:\n                path = trajectory(source, target, horizon, next_hop)\n                value = incremental_value(path)\n                # A positive buffer covers rounding and discourages churn.\n                if value > best_value + 0.75:\n                    best_value = value\n                    best_path = path\n\n        plans[index] = (source, best_path)\n        for k, node in enumerate(best_path):\n            occupancy[k][node] += 1\n\n    return plans\n\n\nclass Strategy:\n    def __init__(self, player_id: int) -> None:\n        self.player_id = player_id\n        self._map_key = None\n        self._map = None\n        self._bad_reports = 0\n\n    def act(self, obs):\n        started = time.perf_counter()\n        deadline = started + max(0.0, 0.6 * TIME_BUDGET)\n        n = int(obs.get("n_nodes", 0))\n        if n <= 0:\n            return []\n\n        key = (n, tuple(tuple(edge) for edge in obs.get("edges", [])))\n        if self._map_key != key:\n            self._map = preprocess_map(n, key[1])\n            self._map_key = key\n\n        if (not obs.get("action_format_correct_last_turn", True)\n                or obs.get("n_invalid_actions_last_turn", 0) > 0):\n            self._bad_reports += 1\n\n        adjacency, distances, next_hop = self._map\n        plans = make_plan(\n            obs, distances, next_hop, deadline,\n            conservative=self._bad_reports >= 2,\n        )\n        return legal_action(plans, obs["player_drones"], adjacency)\n'
_FALLBACK_CLASS = 'Strategy'
_ACT_LIMIT_S = 0.7
_CORE_SHARE = 0.75
_TIME_BUDGET = 0.25
_IMPORT_LIMIT_S = 4.5
_FALLBACK_IMPORT_LIMIT_S = 1.5
_CORE_INIT_LIMIT_S = 2.5
_FALLBACK_INIT_LIMIT_S = 1.5
_MAX_REPLY_CHARS = 900000

_MIN_FALLBACK_S = 0.05
_REPEAT_S = 0.05  # after the first alarm, re-fire every 50 ms until the call returns
_STATE = {"armed": False}
_GUARD_CODES = set()


class _GuardTimeout(BaseException):
    """Raised by the guard's timer. A BaseException: `except Exception` cannot swallow it."""


class _Sink:
    """Swallows output: strategy code must not flood the worker's stderr."""

    encoding = "utf-8"
    errors = "replace"

    def write(self, s):
        return len(s)

    def writelines(self, lines):
        return None

    def flush(self):
        return None

    def isatty(self):
        return False


_SINK = _Sink()


def _noop_print(*args, **kwargs):
    return None


def _on_alarm(signum, frame):
    if _STATE["armed"] and (frame is None or frame.f_code not in _GUARD_CODES):
        raise _GuardTimeout()


def _can_time():
    return (
        hasattr(_signal, "setitimer")
        and hasattr(_signal, "SIGALRM")
        and _threading.current_thread() is _threading.main_thread()
    )


def _plain(value):
    """(True, plain copy) if value is a literal within the reply limit, else (False, None)."""
    try:
        text = repr(value)
        if len(text) > _MAX_REPLY_CHARS:
            return False, None
        if not text.isascii() and len(text.encode("utf-8", "replace")) > _MAX_REPLY_CHARS:
            return False, None  # arena's reply limit counts bytes
        copy = _ast.literal_eval(text)
        if not bool(copy == value):  # NaN, or a type whose repr is not its value
            return False, None
        return True, copy
    except Exception:
        return False, None


def _call(fn, args, limit, check):
    """fn(*args) under a hard timer: (status, value, error, secs). Never raises.

    status: 'ok', 'timeout', 'exception' or 'bad' (check=True and not a plain literal).
    """
    status = "exception"
    value = None
    error = None
    timed = False
    prev_handler = None
    prev_timer = (0.0, 0.0)
    out, err, inp = _sys.stdout, _sys.stderr, _sys.stdin
    t0 = _time.perf_counter()
    try:
        if limit > 0 and _can_time():
            prev_handler = _signal.signal(_signal.SIGALRM, _on_alarm)
            prev_timer = _signal.setitimer(_signal.ITIMER_REAL, limit, _REPEAT_S)
            timed = True
        _sys.stdout = _sys.stderr = _SINK
        _sys.stdin = None  # arena's protocol pipe: untrusted code must not read it
        _STATE["armed"] = timed
        try:
            result = fn(*args)
            if check:
                ok, result = _plain(result)
                status = "ok" if ok else "bad"
            else:
                status = "ok"
            value = result
        except _GuardTimeout as e:
            status = "timeout"
            error = e
        except BaseException as e:
            status = "exception"
            error = e
    except BaseException as e:
        if status == "exception" and error is None:
            error = e
    finally:
        _STATE["armed"] = False
        if timed:
            try:
                _signal.setitimer(_signal.ITIMER_REAL, 0.0)
                _signal.signal(
                    _signal.SIGALRM, prev_handler if prev_handler is not None else _signal.SIG_DFL
                )
                if prev_timer[0] > 0:
                    spent = _time.perf_counter() - t0
                    _signal.setitimer(
                        _signal.ITIMER_REAL, max(prev_timer[0] - spent, 1e-4), prev_timer[1]
                    )
            except BaseException:
                pass
        _sys.stdout, _sys.stderr, _sys.stdin = out, err, inp
    if isinstance(error, _GuardTimeout):
        status = "timeout"
    return status, value, error, _time.perf_counter() - t0


_GUARD_CODES.add(_call.__code__)  # exempt already while the embedded sources load


def _act_of(strategy, obs):
    """strategy.act(obs): inside the timed call, so a missing or broken `act` is caught too."""
    return strategy.act(obs)


def _describe(status, error, secs, limit):
    if status == "timeout":
        where = ""
        try:
            if error is not None:
                frames = _traceback.extract_tb(error.__traceback__)
                frames = [f for f in frames if f.name not in ("_on_alarm", "_call")][-3:]
                where = "\ninterrupted at:\n" + "".join(_traceback.format_list(frames))
        except BaseException:
            where = ""
        return "timeout: no result within %.2f s (limit %.2f s)%s" % (secs, limit, where[-1500:])
    if status == "bad":
        return "bad output: not a plain Python literal within the reply limit"
    try:
        return "".join(_traceback.format_exception(error))[-4000:]
    except BaseException:
        return "exception (traceback unavailable)"


def _load(src, cls_name, label):
    n = 0
    while "_hz_%s_%d" % (label, n) in _sys.modules:
        n += 1
    name = "_hz_%s_%d" % (label, n)
    filename = "<%s>" % name
    _linecache.cache[filename] = (len(src), None, src.splitlines(True), filename)
    module = _types.ModuleType(name)
    module.__file__ = filename
    module.TIME_BUDGET = _TIME_BUDGET
    module.print = _noop_print
    _sys.modules[name] = module
    try:
        exec(compile(src, filename, "exec"), module.__dict__)
        module.TIME_BUDGET = _TIME_BUDGET
        module.print = _noop_print
        return getattr(module, cls_name)
    except BaseException:
        _sys.modules.pop(name, None)
        raise


_LOAD_ERRORS = {}


def _load_all():
    t0 = _time.perf_counter()
    loaded = {"core": None, "fallback": None}
    parts = (
        ("fallback", _FALLBACK_SRC, _FALLBACK_CLASS, _FALLBACK_IMPORT_LIMIT_S),
        ("core", _CORE_SRC, _CORE_CLASS, None),
    )
    for label, src, cls_name, limit in parts:
        if src is None:
            continue
        left = _IMPORT_LIMIT_S - (_time.perf_counter() - t0)
        limit = min(limit, left) if limit is not None else left
        limit = max(limit, 0.5)
        status, value, error, secs = _call(_load, (src, cls_name, label), limit, False)
        if status == "ok":
            loaded[label] = value
        else:
            _LOAD_ERRORS[label] = _describe(status, error, secs, limit)
    return loaded["core"], loaded["fallback"]


try:
    _CORE_CLS, _FALLBACK_CLS = _load_all()
except BaseException:
    _CORE_CLS, _FALLBACK_CLS = None, None


class _HzGuard:
    def __init__(self, player_id):
        self.player_id = player_id
        self._core = None
        self._fallback = None
        self._stats = {
            "turns": 0,
            "core_ok": 0,
            "core_exceptions": 0,
            "core_timeouts": 0,
            "core_bad_output": 0,
            "fallback_used": 0,
            "fallback_failures": 0,
            "none_used": 0,
            "max_core_s": 0.0,
            "first_core_traceback": _LOAD_ERRORS.get("core"),
            "core_loaded": _CORE_CLS is not None,
            "fallback_loaded": _FALLBACK_CLS is not None,
            "core_init_error": None,
            "fallback_init_error": None,
            "fallback_load_error": _LOAD_ERRORS.get("fallback"),
            "first_fallback_error": None,
        }
        try:
            if _CORE_CLS is not None:
                lim = _CORE_INIT_LIMIT_S
                status, value, error, secs = _call(_CORE_CLS, (player_id,), lim, False)
                if status == "ok":
                    self._core = value
                else:
                    msg = _describe(status, error, secs, lim)
                    self._stats["core_init_error"] = msg
                    if self._stats["first_core_traceback"] is None:
                        self._stats["first_core_traceback"] = msg
            if _FALLBACK_CLS is not None:
                lim = _FALLBACK_INIT_LIMIT_S
                status, value, error, secs = _call(_FALLBACK_CLS, (player_id,), lim, False)
                if status == "ok":
                    self._fallback = value
                else:
                    self._stats["fallback_init_error"] = _describe(status, error, secs, lim)
        except BaseException:
            pass

    def act(self, obs):
        try:
            return self._act(obs)
        except BaseException:
            return None

    def _act(self, obs):
        t0 = _time.perf_counter()
        st = self._stats
        st["turns"] += 1
        core, fallback = self._core, self._fallback
        saved = None
        if core is not None:
            if fallback is not None:
                try:
                    saved = repr(obs)  # the core may mutate obs; the fallback gets a fresh copy
                except Exception:
                    saved = None
            limit = _ACT_LIMIT_S * _CORE_SHARE
            status, value, error, secs = _call(_act_of, (core, obs), limit, True)
            if secs > st["max_core_s"]:
                st["max_core_s"] = secs
            if status == "ok":
                st["core_ok"] += 1
                return value
            if status == "timeout":
                st["core_timeouts"] += 1
            elif status == "bad":
                st["core_bad_output"] += 1
            else:
                st["core_exceptions"] += 1
            if st["first_core_traceback"] is None:
                st["first_core_traceback"] = _describe(status, error, secs, limit)
            error = None
        if fallback is not None:
            fobs = obs
            if saved is not None:
                try:
                    fobs = _ast.literal_eval(saved)
                except Exception:
                    fobs = obs
            left = _ACT_LIMIT_S - (_time.perf_counter() - t0)
            if left >= _MIN_FALLBACK_S:
                status, value, error, secs = _call(_act_of, (fallback, fobs), left, True)
                if status == "ok":
                    st["fallback_used"] += 1
                    return value
                st["fallback_failures"] += 1
                if st["first_fallback_error"] is None:
                    st["first_fallback_error"] = _describe(status, error, secs, left)
        st["none_used"] += 1
        return None

    def guard_stats(self):
        """Counters of this instance: how often the core answered, failed, fell back."""
        try:
            return dict(self._stats)
        except BaseException:
            return {}


for _fn in (_call, _HzGuard.__init__, _HzGuard.act, _HzGuard._act, _HzGuard.guard_stats):
    _GUARD_CODES.add(_fn.__code__)
del _fn


class Strategy(_HzGuard):
    """Guarded strategy: never raises, never exceeds its time limit."""
